def _apply_protectedpath_streams_customizations():  # isort: skip
    """ProtectedpathStreams-specific overrides applied at import time.

    Stream membership spans three write endpoints (add_stream, remove_stream,
    modify_member) and there is no GET for the streams themselves, so current
    state is read from the parent protected path object to drive idempotent
    add/modify/remove. Wrapped in a function so ansible-doc's AST parser does
    not choke on attribute patches at module level.
    """
    from typing import Any, Dict, List, Optional

    from ansible_collections.vastdata.vms.plugins.module_utils.vast.errors import VastAPIError

    ProtectedpathStreams.module_result_key = "protectedpath_stream"
    ProtectedpathStreams._ADD_FIELDS = {
        "name",
        "protection_policy_id",
        "target_exported_dir",
        "remote_tenant_guid",
        "capabilities",
        "remote_target_id",
        "sync_interval",
        "lease_expiry_time",
        "sync_disconnect_time",
        "source_member_capabilities",
        "view_replication_enabled",
    }
    ProtectedpathStreams._MODIFY_FIELDS = {
        "capabilities",
        "lease_expiry_time",
        "source_member_capabilities",
        "sync_disconnect_time",
        "sync_interval",
    }

    def _run(self) -> None:
        if self.params.get("state", "present") == "absent":
            self._ensure_absent()
        else:
            self._ensure_present()

    def _ensure_present(self) -> None:
        self._require("name")
        current = self._find_current_stream()
        if not current:
            self._require("target_exported_dir")
            payload = self._build_action_payload(self._ADD_FIELDS)
            result = self._patch_action("add_stream", payload)
            self._exit_changed({}, result or payload)

        modify_payload = self._modify_payload_for(current)
        if modify_payload:
            result = self._patch_action("modify_member", modify_payload)
            self._exit_changed(current, result or {**current, **modify_payload})

        self.module.exit_json(changed=False, **{self.module_result_key: current})

    def _ensure_absent(self) -> None:
        current = self._find_current_stream()
        if not current:
            self.module.exit_json(changed=False, **{self.module_result_key: {}})

        stream_id = self._stream_id(current)
        if stream_id is None:
            self.module.fail_json(msg="stream_id is required because the existing stream ID could not be resolved")

        payload = {"stream_id": str(stream_id)}
        result = self._patch_action("remove_stream", payload)
        self._exit_changed(current, result or {})

    def _find_current_stream(self) -> Optional[Dict[str, Any]]:
        protected_path = self._get_protected_path()
        streams = self._extract_streams(protected_path)
        return self._find_stream(streams, self.params.get("stream_id"), self.params.get("name"))

    def _get_protected_path(self) -> Dict[str, Any]:
        protectedpath_id = self.params[self.parent_id_param]
        try:
            result = self.client.api[self.parent_resource][protectedpath_id].first()
        except VastAPIError as e:
            raise VastAPIError(f"Failed to read protected path {protectedpath_id}: {e}") from e

        if not result:
            self.module.fail_json(msg=f"Protected path {protectedpath_id} was not found")
        return result

    def _extract_streams(self, protected_path: Dict[str, Any]) -> List[Dict[str, Any]]:
        streams: List[Dict[str, Any]] = []
        for key in ("replication_streams", "members_info", "streams"):
            value = protected_path.get(key)
            if isinstance(value, list):
                streams.extend([item for item in value if isinstance(item, dict)])
        return streams

    def _find_stream(
        self,
        streams: List[Dict[str, Any]],
        stream_id: Optional[str],
        name: Optional[str],
    ) -> Optional[Dict[str, Any]]:
        for stream in streams:
            current_id = self._stream_id(stream)
            if stream_id is not None and current_id is not None and str(current_id) == str(stream_id):
                return stream
            if name and self._stream_name(stream) == name:
                return stream
        return None

    def _stream_id(self, stream: Dict[str, Any]) -> Optional[Any]:
        return self._first_value(stream, ("stream_id", "id"), nested=("replication_stream", "stream", "member"))

    def _stream_name(self, stream: Dict[str, Any]) -> Optional[str]:
        value = self._first_value(stream, ("name",), nested=("replication_stream", "stream", "member"))
        return str(value) if value is not None else None

    def _stream_capabilities(self, stream: Dict[str, Any]) -> Optional[str]:
        value = self._first_value(
            stream, ("capabilities", "member_capabilities"), nested=("replication_stream", "stream", "member")
        )
        return str(value) if value is not None else None

    def _stream_field(self, stream: Dict[str, Any], field: str) -> Optional[Any]:
        return self._first_value(stream, (field,), nested=("replication_stream", "stream", "member"))

    @staticmethod
    def _first_value(stream: Dict[str, Any], keys: tuple, nested: tuple = ()) -> Optional[Any]:
        for key in keys:
            if stream.get(key) is not None:
                return stream[key]
        for nested_key in nested:
            nested_obj = stream.get(nested_key)
            if not isinstance(nested_obj, dict):
                continue
            for key in keys:
                if nested_obj.get(key) is not None:
                    return nested_obj[key]
        return None

    def _modify_payload_for(self, current: Dict[str, Any]) -> Dict[str, Any]:
        stream_id = self.params.get("stream_id") or self._stream_id(current)
        if not stream_id:
            return {}

        payload: Dict[str, Any] = {"stream_id": str(stream_id)}

        for field in self._MODIFY_FIELDS:
            desired = self.params.get(field)
            if desired is None:
                continue
            current_value = self._stream_capabilities(current) if field == "capabilities" else self._stream_field(current, field)
            if str(current_value) != str(desired):
                payload[field] = desired

        if len(payload) == 1:
            return {}

        if "capabilities" not in payload and self._stream_capabilities(current):
            payload["capabilities"] = self._stream_capabilities(current)

        return payload

    def _build_action_payload(self, allowed_fields: set) -> Dict[str, Any]:
        return {key: self.params[key] for key in allowed_fields if self.params.get(key) is not None}

    def _patch_action(self, action: str, payload: Dict[str, Any]) -> Dict[str, Any]:
        if self.check_mode:
            return payload

        try:
            result = self._api_for_action(action).patch(**payload)
        except VastAPIError as e:
            raise VastAPIError(f"Failed to {action} on protected path {self.params[self.parent_id_param]}: {e}") from e

        self._wait_for_task(result)
        return result or {}

    def _require(self, *params: str) -> None:
        missing = [param for param in params if self.params.get(param) is None]
        if missing:
            self.module.fail_json(msg="Missing required parameters: {}".format(", ".join(missing)))

    def _exit_changed(self, before: Dict[str, Any], after: Dict[str, Any]) -> None:
        self.module.exit_json(changed=True, **{self.module_result_key: after}, diff={"before": before, "after": after})

    ProtectedpathStreams.run = _run
    ProtectedpathStreams._ensure_present = _ensure_present
    ProtectedpathStreams._ensure_absent = _ensure_absent
    ProtectedpathStreams._find_current_stream = _find_current_stream
    ProtectedpathStreams._get_protected_path = _get_protected_path
    ProtectedpathStreams._extract_streams = _extract_streams
    ProtectedpathStreams._find_stream = _find_stream
    ProtectedpathStreams._stream_id = _stream_id
    ProtectedpathStreams._stream_name = _stream_name
    ProtectedpathStreams._stream_capabilities = _stream_capabilities
    ProtectedpathStreams._stream_field = _stream_field
    ProtectedpathStreams._first_value = _first_value
    ProtectedpathStreams._modify_payload_for = _modify_payload_for
    ProtectedpathStreams._build_action_payload = _build_action_payload
    ProtectedpathStreams._patch_action = _patch_action
    ProtectedpathStreams._require = _require
    ProtectedpathStreams._exit_changed = _exit_changed


_apply_protectedpath_streams_customizations()


